import pandas as pd
import re

df = pd.read_csv('b3_supercon_data.csv')

def get_elements(comp_str):
    matches = re.findall(r'([A-Z][a-z]*)([0-9\.]*)', comp_str)
    res = {}
    for el, amt in matches:
        res[el] = float(amt) if amt else 1.0
    return res

allowed_elements = {'O', 'Cu', 'Ba', 'Sr', 'Y', 'Ca', 'La', 'Bi', 'Fe', 'Nb', 'C', 'Pr', 'As', 'B', 'Pb', 'Ce', 'Mo', 'V', 'Zn', 'Ni'}

best = []
for idx, row in df.iterrows():
    comp = get_elements(row['composition'])
    # check if all elements in comp are in allowed_elements
    if all(el in allowed_elements for el in comp):
        if len(comp) <= 4:
            # normalize
            total = sum(comp.values())
            frac = {el: val/total for el, val in comp.items()}
            best.append((row['target'], row['composition'], frac))

best.sort(key=lambda x: x[0], reverse=True)
for row in best[:20]:
    print(row)
