                'Mo': 1.0, 'V': 0.9918, 'Zn': 1.0, 'Ni': 0.6
            }

            valid = True
            for k, v in frac.items():
                if v > limits.get(k, 0) + 1e-6:
                    valid = False

            if valid and row['target'] > best_tc:
                best_tc = row['target']
                best_comp = row['composition']
                best_fracs = frac

print(f"Best Tc: {best_tc}")
